function handleCellSelection(event) {
    const target = event.target;

    // Solo procesamos si el objetivo es una celda de datos editable (td)
    if (target.tagName === 'TD' && target.hasAttribute('contenteditable')) {
        // 1. Deseleccionar cualquier celda previamente seleccionada
        document.querySelectorAll('.selected-cell').forEach(el => {
            el.classList.remove('selected-cell');
