function setupColumnSelectionAndActions() {
    const headerRow = document.querySelector('#spreadsheet-grid thead tr');
    const spreadsheetBody = document.getElementById('spreadsheet-body');
    const colorPicker = document.getElementById('color-picker');
    const applyButton = document.getElementById('apply-format-btn');

    let selectedColumnHeader = null;

    // --- 1. Manejar la selección de columna (Click en el encabezado) ---
    headerRow.addEventListener('click', function(event) {
        const target = event.target.closest('.column-header');
        if (!target) return;

        const col = target.getAttribute('data-col');

        // Deseleccionar la columna anterior
        if (selectedColumnHeader) {
            selectedColumnHeader.classList.remove('selected-column');
        }

        // Seleccionar la nueva columna
        selectedColumnHeader = target;
        selectedColumnHeader.classList.add('selected-column');
    });


    // --- 2. Acciones de Columna (Botones/Contexto) ---

    // Función para obtener todas las celdas de una columna dada su letra
    const getCellsInColumn = (col) => {
        let cells = [];
        // Iterar sobre cada fila del cuerpo
        spreadsheetBody.querySelectorAll('tr').forEach(row => {
            const colIndex = row.querySelector(`[data-col="${col}"]`);
            if (colIndex) {
                cells.push(colIndex);
            }
        });
        return cells;
    };

    // Acción: Borrar Columna
    window.deleteColumn = (col) => {
        if (!confirm(`¿Está seguro de que desea eliminar la columna ${col}? Esta acción es irreversible.`)) {
            return;
        }

        // 1. Eliminar el encabezado de la columna
        selectedColumnHeader.remove();

        // 2. Iterar sobre todas las filas y eliminar la celda correspondiente
        spreadsheetBody.querySelectorAll(`[data-col="${col}"]`).forEach(cell => {
            cell.remove();
        });
    };

    // Acción: Borrar Contenido de Columna
    window.clearColumn = (col) => {
        if (!confirm(`¿Desea borrar el contenido de toda la columna ${col}?`)) {
            return;
        }

        const cells = getCellsInColumn(col);
        cells.forEach(cell => {
            // Limpiar texto y resetear formato (aunque CSS lo maneje, es bueno limpiar el DOM)
            cell.textContent = '';
            cell.style.backgroundColor = ''; 
        });
    };

    // Acción: Cambiar Color de Fondo de Columna
    const formatColumn = (col, color) => {
        if (!color) return;

        const cells = getCellsInColumn(col);
        cells.forEach(cell => {
            cell.style.backgroundColor = color;
        });
    };


    // --- 3. Integración de la UI para las acciones (Botón/Contexto) ---

    // Sobrescribimos o complementamos la funcionalidad del botón existente:
    applyButton.addEventListener('click', () => {
        if (!selectedColumnHeader) {
            alert("Por favor, selecciona una columna primero.");
            return;
        }

        const col = selectedColumnHeader.getAttribute('data-col');
        const color = colorPicker.value;

        // Aplicaremos el formato a TODA LA COLUMNA (R6: Cambiar fondo de todas sus celdas)
        formatColumn(col, color);
    });
}
