function setupCellSelectionAndFormatting() {
    const spreadsheetBody = document.getElementById('spreadsheet-body');
    const colorPicker = document.getElementById('color-picker');
    const applyButton = document.getElementById('apply-format-btn');

    // Elementos de control de columna (R6)
    const columnHeaders = document.querySelectorAll('.col-header');
    const selectedColumnDisplay = document.getElementById('selected-column-display');
    const deleteColumnBtn = document.getElementById('delete-column-btn');
    const clearColumnContentBtn = document.getElementById('clear-column-content-btn');
    const formatColumnBgBtn = document.getElementById('format-column-bg-btn');

    let selectedCell = null;
    let activeColumn = null; // Almacena la columna activa (ej: 'A')

    // --- Lógica de Selección de Columna (R6) ---
    const handleColumnSelection = (event) => {
        const target = event.target;
        if (!target.classList.contains('col-header')) return;

        const col = target.getAttribute('data-col');

        // Deseleccionar columna anterior
        columnHeaders.forEach(th => th.classList.remove('selected'));

        // Seleccionar nueva columna
        target.classList.add('selected');
        activeColumn = col;
        selectedColumnDisplay.textContent = col;
        selectedColumnDisplay.classList.add('active-col');

        // Habilitar/Deshabilitar botones de acción
        const isDisabled = !activeColumn;
        deleteColumnBtn.disabled = isDisabled;
        clearColumnContentBtn.disabled = isDisabled;
        formatColumnBgBtn.disabled = isDisabled;
    };

    columnHeaders.forEach(header => {
        header.addEventListener('click', handleColumnSelection);
    });


    // 1. Manejar la selección de celdas (Click) - Mantenido para R5
    spreadsheetBody.addEventListener('click', function(event) {
        const target = event.target;

        if (target.tagName === 'TD' && target.hasAttribute('contenteditable')) {
            // Deseleccionar el anterior
            if (selectedCell) {
                selectedCell.style.outline = '';
            }

            // Seleccionar el nuevo objetivo
            selectedCell = target;
            selectedCell.style.outline = '2px solid blue'; // Indicador visual de selección
        }
    });

    // 2. Manejar la aplicación del color (Botón o Input) - Mantenido para R5
    const applyColor = () => {
        if (!selectedCell) {
            alert("Por favor, selecciona una celda primero.");
            return;
        }

        const selectedColor = colorPicker.value;
        // Aplicar el fondo de color seleccionado a la celda activa
        selectedCell.style.backgroundColor = selectedColor;
    };

    // Evento para el botón "Aplicar Formato"
    applyButton.addEventListener('click', applyColor);


    // --- Funcionalidades de Columna (R6) ---

    /** Borra la columna seleccionada y actualiza la estructura del DOM. */
    const deleteColumn = () => {
        if (!activeColumn) return;

        if (!confirm(`¿Estás seguro de que deseas borrar la columna ${activeColumn}? Esta acción es irreversible.`)) {
            return;
        }

        // 1. Eliminar el encabezado de la columna
        const headerToRemove = document.querySelector(`.col-header[data-col="${activeColumn}"]`);
        if (headerToRemove) {
            headerToRemove.remove();
        }

        // 2. Iterar sobre todas las filas y eliminar la celda correspondiente
        const rows = spreadsheetBody.querySelectorAll('tr');
        rows.forEach(row => {
            const cellToRemove = row.querySelector(`[data-col="${activeColumn}"]`);
            if (cellToRemove) {
                cellToRemove.remove();
            }
        });

        // 3. Resetear el estado de la columna
        activeColumn = null;
        selectedColumnDisplay.textContent = 'Ninguna';
        selectedColumnDisplay.classList.remove('active-col');
        deleteColumnBtn.disabled = true;
        clearColumnContentBtn.disabled = true;
        formatColumnBgBtn.disabled = true;

        // 4. Limpiar la selección de celda visual
        if (selectedCell) {
            selectedCell.style.outline = '';
            selectedCell = null;
        }
    };

    /** Limpia el contenido de todas las celdas en la columna seleccionada. */
    const clearColumnContent = () => {
        if (!activeColumn) return;

        if (!confirm(`¿Estás seguro de que deseas limpiar TODO el contenido de la columna ${activeColumn}?`)) {
