        });
    };

    /** Aplica un color de fondo a todas las celdas en la columna seleccionada. */
    const setColumnBackgroundColor = () => {
        if (!activeColumn) return;

        // Usamos el color actual del picker para mantener coherencia con R5
        const selectedColor = colorPicker.value; 

        const rows = spreadsheetBody.querySelectorAll('tr');
        rows.forEach(row => {
            const cell = row.querySelector(`[data-col="${activeColumn}"]`);
            if (cell) {
                // Aplicar el fondo de color seleccionado a la celda activa
                cell.style.backgroundColor = selectedColor;
            }
        });
    };

    // Event Listeners para los nuevos controles R6
    deleteColumnBtn.addEventListener('click', deleteColumn);
    clearColumnContentBtn.addEventListener('click', clearColumnContent);
    formatColumnBgBtn.addEventListener('click', setColumnBackgroundColor);
}
