function setupRowActions() {
    const spreadsheetBody = document.getElementById('spreadsheet-body');
    const colorPicker = document.getElementById('color-picker');
    const clearBtn = document.getElementById('clear-row-content-btn');
    const formatBtn = document.getElementById('format-row-bg-btn');
    const deleteBtn = document.getElementById('delete-row-btn');

    // Función para actualizar el estado de los botones basado en la selección de fila/columna
    const updateRowActionButtons = (selectedElement) => {
        if (!selectedElement || !selectedElement.closest('tr')) {
            clearBtn.disabled = true;
            formatBtn.disabled = true;
            deleteBtn.disabled = true;
            return;
        }

        // Si se ha seleccionado un elemento dentro de una fila (TD o TH)
        const row = selectedElement.closest('tr');
        if (row && row.parentElement === spreadsheetBody) {
             clearBtn.disabled = false;
             formatBtn.disabled = false;
             deleteBtn.disabled = false;
        } else {
            // Si la selección no está dentro del tbody, deshabilitar acciones de fila
            clearBtn.disabled = true;
            formatBtn.disabled = true;
            deleteBtn.disabled = true;
        }
    };

    // 1. Manejar el clic en cualquier parte de una fila (TD o TH) para activar las acciones de fila
    spreadsheetBody.addEventListener('click', function(event) {
        const target = event.target;
        if (target.tagName === 'TD' || target.tagName === 'TH') {
            // Si el clic fue en cualquier celda, actualizamos los botones para habilitar acciones de fila
            updateRowActionButtons(target);
        } else if (target.closest('tr')) {
             // Si se hizo clic en un área que contiene una fila pero no es una TD/TH directa (ej: el fondo del tr)
             const row = target.closest('tr');
             if (row && row.parentElement === spreadsheetBody) {
                 updateRowActionButtons(target);
             }
        } else {
            // Si se hace clic fuera de cualquier celda, deshabilitar acciones de fila
            updateRowActionButtons(null);
        }
    });

    // 2. Evento para borrar contenido de la fila
    clearBtn.addEventListener('click', () => {
        const selectedRow = document.querySelector('#spreadsheet-body tr[data-row*=""]'); // Asume que el primer TR es el seleccionado si no hay estado global
        if (selectedRow) {
            // Iterar sobre todas las celdas de la fila y limpiar su contenido
            Array.from(selectedRow.querySelectorAll('td')).forEach(cell => {
                cell.textContent = '';
                cell.innerHTML = '';
            });
        }
    });

    // 3. Evento para cambiar el fondo de la fila
    formatBtn.addEventListener('click', () => {
        const selectedRow = document.querySelector('#spreadsheet-body tr[data-row*=""]');
        if (selectedRow) {
            const selectedColor = colorPicker.value;
            // Aplicar el fondo a todas las celdas de la fila
            Array.from(selectedRow.querySelectorAll('td')).forEach(cell => {
                cell.style.backgroundColor = selectedColor;
            });
        }
    });

    // 4. Evento para borrar la fila completa
    deleteBtn.addEventListener('click', () => {
        if (confirm("¿Está seguro de que desea eliminar esta fila por completo? Esta acción no se puede deshacer.")) {
            const selectedRow = document.querySelector('#spreadsheet-body tr[data-row*=""]');
            if (selectedRow) {
                selectedRow.remove();
            }
        }
    });
}
