        const row = cell.getAttribute('data-row');
        const key = `${col}${row}`;

        // Recuperar el valor guardado de localStorage
        let storedValue = localStorage.getItem(key);

        if (storedValue !== null) {
            // Restaurar el contenido de la celda
            cell.textContent = storedValue;
        } else {
             // Si no hay nada en storage, asegurarse que esté vacío si es necesario
             // Esto ayuda a mantener la consistencia visual si se borra manualmente y luego recarga.
             // Sin embargo, para el requisito de solo cargar datos existentes, esto es suficiente.
        }
    });
}
